    // ФОРМИРОВАНИЕ АДРЕСА
    // =========================================================

    function getAddress() {
        const region = getFieldByLabel(
            ['Регион'],
            ''
        );

        const district = getFieldByLabel(
            ['Район'],
            ''
        );

        const street = getFieldByLabel(
            ['Улица'],
            ''
        );

        const house = getFieldByLabel(
            ['Дом'],
            ''
        );

        const corpus = getFieldByLabel(
            ['Корпус'],
            ''
        );

        const building = getFieldByLabel(
            ['Стр.', 'Строение'],
            ''
        );

        const entrance = getFieldByLabel(
            ['Подъезд'],
            ''
        );

        const floor = getFieldByLabel(
            ['Этаж'],
            ''
        );

        const apartment = getFieldByLabel(
            ['Квартира'],
            ''
        );

        const parts = [];

        if (region) {
            parts.push(region);
        }

        if (district) {
            parts.push(district);
        }

        if (street) {
            parts.push(`ул. ${street}`);
        }

        if (house) {
            parts.push(`д. ${house}`);
        }

        if (corpus) {
            parts.push(`корп. ${corpus}`);
        }

        if (building) {
            parts.push(`стр. ${building}`);
        }

        if (entrance && entrance !== '0') {
            parts.push(`под. ${entrance}`);
        }

        if (floor && floor !== '0') {
            parts.push(`эт. ${floor}`);
        }

        if (apartment) {
            parts.push(`кв. ${apartment}`);
        }

        return parts.length
            ? parts.join(', ')
            : 'Не найден';
    }

