    // =========================================================
    // ЗВУК
    // =========================================================

    function playDingSound() {
        try {
            const AudioContext =
                window.AudioContext ||
                window.webkitAudioContext;

            if (!AudioContext) {
                return;
            }

            const ctx = new AudioContext();

            const osc1 = ctx.createOscillator();
            const osc2 = ctx.createOscillator();
            const gainNode = ctx.createGain();

            osc1.type = 'sine';
            osc1.frequency.setValueAtTime(
                850,
                ctx.currentTime
            );

            osc2.type = 'triangle';
            osc2.frequency.setValueAtTime(
                1200,
                ctx.currentTime
            );

            gainNode.gain.setValueAtTime(
                0.3,
                ctx.currentTime
            );

            gainNode.gain.exponentialRampToValueAtTime(
                0.001,
                ctx.currentTime + 0.4
            );

            osc1.connect(gainNode);
            osc2.connect(gainNode);
            gainNode.connect(ctx.destination);

            osc1.start();
            osc2.start();

            osc1.stop(
                ctx.currentTime + 0.4
            );

            osc2.stop(
                ctx.currentTime + 0.4
            );

        } catch (error) {
            console.error(
                'Не удалось воспроизвести звук:',
                error
            );
        }
    }

    // =========================================================
    // КОПИРОВАНИЕ
    // =========================================================

    function collectAndCopyData() {

        // Проверяем, что мы действительно на нужном сайте
        if (
            location.hostname !==
            'adviser-new.101internet.ru'
        ) {
            return;
        }

        if (!location.pathname.startsWith('/orders/')) {
            return;
        }

        const resultText = collectData();

        try {

            GM_setClipboard(
                resultText,
                'text',
                function () {

                    playDingSound();

                    const button =
                        document.getElementById(BUTTON_ID);

                    if (button) {
                        button.classList.remove(
                            'tm-copy-success'
                        );

                        // Перезапускаем animation
                        void button.offsetWidth;

                        button.classList.add(
                            'tm-copy-success'
                        );
                    }

                    console.log(
                        'Данные заявки скопированы:\n',
                        resultText
                    );
                }
            );

        } catch (error) {

            console.error(
                'Ошибка GM_setClipboard:',
                error
            );

            // Запасной вариант
            navigator.clipboard.writeText(
                resultText
            ).then(() => {

                playDingSound();

                const button =
                    document.getElementById(BUTTON_ID);

                if (button) {
                    button.classList.remove(
                        'tm-copy-success'
                    );

                    void button.offsetWidth;

                    button.classList.add(
                        'tm-copy-success'
                    );
                }

            }).catch(() => {

                alert(
                    'Не удалось скопировать данные в буфер обмена.'
                );

            });
        }
    }

