    // =========================================================
    // НОРМАЛИЗАЦИЯ
    // =========================================================

    function normalize(text) {

        return String(text || '')
            .toLowerCase()
            .replace(/ё/g, 'е')
            .replace(/[—–−]/g, '-')
            .replace(/\s+/g, ' ')
            .trim();

    }


    // =========================================================
    // ПОИСК РЕГИОНА
    // =========================================================

    function findRegion(text) {

        const value = normalize(text);

        if (!value) {
            return null;
        }

        for (const region of REGIONS) {

            const variants = [
                region.name,
                ...(region.aliases || [])
            ];

            for (const variant of variants) {

                const normalized =
                    normalize(variant);

                if (
                    value === normalized ||
                    value.includes(normalized) ||
                    normalized.includes(value)
                ) {
                    return region;
                }

            }

        }

        return null;
    }



    // =========================================================
    // ОФЛАЙН-БАЗА НАСЕЛЁННЫХ ПУНКТОВ РФ
    // Источник: settlements.csv, загруженный пользователем.
    // В базе ~82 тыс. уникальных названий населённых пунктов.
    // Для каждого названия хранится список индексов субъектов РФ.
    // Интернет для поиска не требуется.
    // =========================================================

    // Офлайн-база населённых пунктов хранится в сжатом виде.
    // Она распаковывается только при первом поиске региона,
    // чтобы большая база не блокировала загрузку страницы.
    let CITY_DB = null;
    let CITY_DB_PROMISE = null;
    const CITY_DB_GZIP_BASE64 =
        "";

    async function loadCityDb() {
        if (CITY_DB) return CITY_DB;
        if (CITY_DB_PROMISE) return CITY_DB_PROMISE;

        CITY_DB_PROMISE = (async () => {
            const binary = atob(CITY_DB_GZIP_BASE64);
            const bytes = new Uint8Array(binary.length);
            for (let i = 0; i < binary.length; i++) {
                bytes[i] = binary.charCodeAt(i);
            }

            if (typeof DecompressionStream === 'undefined') {
                throw new Error('Браузер не поддерживает распаковку локальной базы. Обновите Chrome/Edge.');
            }

            const stream = new Blob([bytes])
                .stream()
                .pipeThrough(new DecompressionStream('gzip'));

            const buffer = await new Response(stream).arrayBuffer();
            const json = new TextDecoder('utf-8').decode(buffer);
            CITY_DB = JSON.parse(json);
            return CITY_DB;
        })();

        try {
            return await CITY_DB_PROMISE;
        } catch (error) {
            CITY_DB_PROMISE = null;
            throw error;
        }
    }

    function normalizeCity(value) {
        let s = normalize(value)
            .replace(/^город\s+/i, '')
            .replace(/^г\.\s*/i, '')
            .replace(/^г\s+/i, '')
            .replace(/^(пгт|рп|п\.?|с\.?|д\.?|х\.?|аул|ст-ца|ст\.?|нп)\s+/i, '')
            .trim();

        return s;
    }

    async function findLocalCityRegions(city) {
        const value = normalizeCity(city);
        if (!value) return [];

        const db = await loadCityDb();
        const ids = db[value];
        if (!ids) return [];

        return ids
            .map(id => REGIONS[id])
            .filter(Boolean);
    }

    async function searchLocalCity(city) {
        const regions = await findLocalCityRegions(city);

        if (!regions.length) {
            return null;
        }

        return {
            name: city.trim(),
            address: { city: city.trim() },
            display_name: city.trim(),
            _localRegions: regions
        };
    }

    function showMultipleLocalResults(city, regions) {
        const box = document.getElementById('tm-rf-result');
        if (!box) return;

        const items = regions.map((region, index) => `
            <div class="tm-rf-item">
                <span>${index + 1}</span>
                <strong>${escapeHtml(region.name)}</strong>
            </div>
        `).join('');

        box.innerHTML = `
            <div class="tm-rf-warning">
                ⚠ Найдено несколько субъектов РФ
            </div>
            <div class="tm-rf-small">
                Населённых пунктов с названием
                «${escapeHtml(city.trim())}» несколько.
                Выберите нужный субъект:
            </div>
            <div class="tm-rf-info">
                ${items}
            </div>
        `;
    }

    // =========================================================
    // РЕГИОН ИЗ РЕЗУЛЬТАТА
    // =========================================================

    function getRegionFromResult(result) {

        if (!result) {
            return null;
        }

        const address =
            result.address || {};

        const fields = [

            address.state,
            address.region,
            address.province,
            address.state_district,
            address.county

        ];

        for (const field of fields) {

            const region =
                findRegion(field);

            if (region) {
                return region;
            }

        }

        return findRegion(
            result.display_name
        );

    }


    // =========================================================
    // НАЗВАНИЕ ГОРОДА
    // =========================================================

    function getCityName(result) {

        const address =
            result.address || {};

        return (
            address.city ||
            address.town ||
            address.village ||
            address.municipality ||
            result.name ||
            'Не определён'
        );

    }


    // =========================================================
    // HTML ESCAPE
    // =========================================================

    function escapeHtml(value) {

        return String(value || '')
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#039;');

    }


    // =========================================================
    // ОШИБКА
    // =========================================================

    function showError(message) {

        const box =
            document.getElementById(
                'tm-rf-result'
            );

        if (!box) {
            return;
        }

        box.innerHTML = `
            <div class="tm-rf-error">
                ⚠ ${escapeHtml(message)}
            </div>
        `;

    }


    // =========================================================
    // РЕЗУЛЬТАТ
    // =========================================================

    function showResult(result, region) {

        const box =
            document.getElementById(
                'tm-rf-result'
            );

        if (!box) {
            return;
        }

        const city =
            getCityName(result);

        box.innerHTML = `

            <div class="tm-rf-success">
                ✓ Регион определён
            </div>

            <div class="tm-rf-info">

                <div class="tm-rf-item">
                    <span>Город</span>
                    <strong>
                        ${escapeHtml(city)}
                    </strong>
                </div>

                <div class="tm-rf-item">
                    <span>Субъект РФ</span>
                    <strong>
                        ${escapeHtml(region.name)}
                    </strong>
                </div>

                <div class="tm-rf-item">
                    <span>Тип субъекта</span>
                    <strong>
                        ${escapeHtml(region.type)}
                    </strong>
                </div>

                <div class="tm-rf-item">
                    <span>Код региона</span>
                    <strong>
                        ${escapeHtml(region.code)}
                    </strong>
                </div>

                <div class="tm-rf-item">
                    <span>Федеральный округ</span>
                    <strong>
                        ${escapeHtml(region.district)}
                    </strong>
                </div>

            </div>

            <button
                id="tm-rf-copy"
                type="button"
            >
                📋 Скопировать
            </button>
        `;


        const copyButton =
            document.getElementById(
                'tm-rf-copy'
            );


        copyButton.addEventListener(
            'click',
            async function () {

                const text =
`Город: ${city}
Субъект РФ: ${region.name}
Тип субъекта: ${region.type}
Код региона: ${region.code}
Федеральный округ: ${region.district}`;

                try {

                    await navigator.clipboard
                        .writeText(text);

                    copyButton.textContent =
                        '✓ Скопировано';

                    setTimeout(() => {

                        copyButton.textContent =
                            '📋 Скопировать';

                    }, 1500);

                } catch (error) {

                    showError(
                        'Не удалось скопировать результат.'
                    );

                }

            }
        );

    }



    // =========================================================
    // ПОИСК ГОРОДА
    // =========================================================

    async function searchCity() {

        const input =
            document.getElementById(
                'tm-rf-city'
            );

        const resultBox =
            document.getElementById(
                'tm-rf-result'
            );

        if (!input || !resultBox) {
            return;
        }

        const city = input.value.trim();

        if (!city) {
            showError('Введите название города.');
            input.focus();
            return;
        }

        resultBox.innerHTML = `
            <div class="tm-rf-loading">
                🔎 Ищу в локальной базе населённых пунктов...
            </div>
        `;

        const button =
            document.getElementById(
                'tm-rf-search'
            );

        if (button) {
            button.disabled = true;
            button.textContent = '⏳ Поиск...';
        }

        try {

            const result =
                await searchLocalCity(city);

            if (!result || !result._localRegions.length) {

                showError(
                    'Населённый пункт не найден в локальной базе.'
                );

                return;
            }

            if (result._localRegions.length > 1) {

                showMultipleLocalResults(
                    city,
                    result._localRegions
                );

                return;
            }

            showResult(
                result,
                result._localRegions[0]
            );

        } catch (error) {

            console.error(
                '[TM РФ Регион]',
                error
            );

            showError(
                error.message ||
                'Ошибка поиска.'
            );

        } finally {

            if (button) {

                button.disabled = false;

                button.textContent =
                    '🔎 Найти';

            }

        }

    }


    // =========================================================
    // DRAG & DROP
    // =========================================================

    function makeDraggable(panel, header) {

        let dragging = false;

        let offsetX = 0;
        let offsetY = 0;


        header.addEventListener(
            'mousedown',
            function (event) {

                // Кнопки не должны запускать перетаскивание

                if (
                    event.target.closest(
                        '#tm-rf-minimize'
                    ) ||
                    event.target.closest(
                        '#tm-rf-close'
                    )
                ) {
                    return;
                }


                dragging = true;


                const rect =
                    panel.getBoundingClientRect();


                offsetX =
                    event.clientX - rect.left;

                offsetY =
                    event.clientY - rect.top;


                panel.style.left =
                    rect.left + 'px';

                panel.style.top =
                    rect.top + 'px';

                panel.style.right =
                    'auto';

                panel.style.bottom =
                    'auto';


                header.classList.add(
                    'tm-rf-dragging'
                );


                event.preventDefault();

            }
        );


        document.addEventListener(
            'mousemove',
            function (event) {

                if (!dragging) {
                    return;
                }


                let left =
                    event.clientX - offsetX;

                let top =
                    event.clientY - offsetY;


                const width =
                    panel.offsetWidth;


                const height =
                    panel.offsetHeight;


                left = Math.max(
                    0,
                    Math.min(
                        left,
                        window.innerWidth - width
                    )
                );


                top = Math.max(
                    0,
                    Math.min(
                        top,
                        window.innerHeight - height
                    )
                );


                panel.style.left =
                    left + 'px';

                panel.style.top =
                    top + 'px';

            }
        );


        document.addEventListener(
            'mouseup',
            function () {

                if (!dragging) {
                    return;
                }


                dragging = false;


                header.classList.remove(
                    'tm-rf-dragging'
                );


                savePosition(panel);

            }
        );

    }


    // =========================================================
    // СОХРАНЕНИЕ ПОЗИЦИИ
    // =========================================================

    function savePosition(panel) {

        const data = {

            left:
                parseInt(
                    panel.style.left,
                    10
                ),

            top:
                parseInt(
                    panel.style.top,
                    10
                )

        };


        if (
            Number.isNaN(data.left) ||
            Number.isNaN(data.top)
        ) {
            return;
        }


        localStorage.setItem(
            POSITION_KEY,
            JSON.stringify(data)
        );

    }


    // =========================================================
    // ВОССТАНОВЛЕНИЕ ПОЗИЦИИ
    // =========================================================

    function restorePosition(panel) {

        try {

            const saved =
                localStorage.getItem(
                    POSITION_KEY
                );


            if (!saved) {
                return;
            }


            const data =
                JSON.parse(saved);


            if (
                typeof data.left !== 'number' ||
                typeof data.top !== 'number'
            ) {
                return;
            }


            let left = data.left;
            let top = data.top;


            const width =
                panel.offsetWidth;

            const height =
                panel.offsetHeight;


            left = Math.max(
                0,
                Math.min(
                    left,
                    window.innerWidth - width
                )
            );


            top = Math.max(
                0,
                Math.min(
                    top,
                    window.innerHeight - height
                )
            );


            panel.style.left =
                left + 'px';

            panel.style.top =
                top + 'px';

            panel.style.right =
                'auto';

            panel.style.bottom =
                'auto';

        } catch (error) {

            console.warn(
                '[TM РФ Регион] Не удалось восстановить позицию.',
                error
            );

        }

    }


